-- 社区老年助餐｜MySQL 8.0 初始建表（开发版）
-- 执行前 CREATE DATABASE elder_meal CHARACTER SET utf8mb4;
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, real_name VARCHAR(80), phone VARCHAR(30), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sys_role (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(60) NOT NULL);
CREATE TABLE IF NOT EXISTS sys_user_role (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES sys_user(id), FOREIGN KEY(role_id) REFERENCES sys_role(id));
CREATE TABLE IF NOT EXISTS service_site (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, address VARCHAR(255), phone VARCHAR(30), service_area TEXT, manager_user_id BIGINT, business_status VARCHAR(20) NOT NULL DEFAULT 'OPEN', opening_hours VARCHAR(100), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(manager_user_id) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS sys_user_site (user_id BIGINT NOT NULL, site_id BIGINT NOT NULL, PRIMARY KEY(user_id,site_id), FOREIGN KEY(user_id) REFERENCES sys_user(id), FOREIGN KEY(site_id) REFERENCES service_site(id));
CREATE TABLE IF NOT EXISTS site_closed_day (id BIGINT PRIMARY KEY AUTO_INCREMENT, site_id BIGINT NOT NULL, closed_date DATE NOT NULL, meal_type VARCHAR(20) NOT NULL, reason VARCHAR(200), UNIQUE KEY uk_closed(site_id,closed_date,meal_type), FOREIGN KEY(site_id) REFERENCES service_site(id));
CREATE TABLE IF NOT EXISTS elder (id BIGINT PRIMARY KEY AUTO_INCREMENT, site_id BIGINT NOT NULL, name VARCHAR(80) NOT NULL, birth_date DATE, phone VARCHAR(30), identity_cipher TEXT, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(site_id) REFERENCES service_site(id));
CREATE TABLE IF NOT EXISTS elder_health (elder_id BIGINT PRIMARY KEY, diseases_json JSON, allergen_ids_json JSON, avoid_ingredients_json JSON, preferred_categories_json JSON, disliked_categories_json JSON, health_notes TEXT, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(elder_id) REFERENCES elder(id));
CREATE TABLE IF NOT EXISTS family_binding (id BIGINT PRIMARY KEY AUTO_INCREMENT, family_user_id BIGINT NOT NULL, elder_id BIGINT NOT NULL, proof_file_id BIGINT, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', reviewer_id BIGINT, review_note VARCHAR(500), reviewed_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_family_elder(family_user_id,elder_id), FOREIGN KEY(family_user_id) REFERENCES sys_user(id), FOREIGN KEY(elder_id) REFERENCES elder(id));
CREATE TABLE IF NOT EXISTS subsidy_application (id BIGINT PRIMARY KEY AUTO_INCREMENT, elder_id BIGINT NOT NULL, applicant_user_id BIGINT NOT NULL, proof_file_ids_json JSON, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', reviewer_id BIGINT, review_note VARCHAR(500), reviewed_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(elder_id) REFERENCES elder(id), FOREIGN KEY(applicant_user_id) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS subsidy_entitlement (elder_id BIGINT PRIMARY KEY, is_active TINYINT(1) NOT NULL DEFAULT 0, source_application_id BIGINT, activated_at DATETIME, FOREIGN KEY(elder_id) REFERENCES elder(id));
CREATE TABLE IF NOT EXISTS dish_category (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS allergen (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS dish (id BIGINT PRIMARY KEY AUTO_INCREMENT, category_id BIGINT, name VARCHAR(120) NOT NULL, description TEXT, image_file_id BIGINT, ingredients_json JSON, weight_grams DECIMAL(8,2), original_price DECIMAL(10,2) NOT NULL, elder_price DECIMAL(10,2) NOT NULL, calories_kcal DECIMAL(10,2), protein_grams DECIMAL(10,2), fat_grams DECIMAL(10,2), carb_grams DECIMAL(10,2), sodium_mg DECIMAL(10,2), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES dish_category(id), CONSTRAINT ck_dish_price CHECK(original_price>=0 AND elder_price>=0 AND elder_price<=original_price));
CREATE TABLE IF NOT EXISTS dish_allergen (dish_id BIGINT NOT NULL, allergen_id BIGINT NOT NULL, PRIMARY KEY(dish_id,allergen_id), FOREIGN KEY(dish_id) REFERENCES dish(id), FOREIGN KEY(allergen_id) REFERENCES allergen(id));
CREATE TABLE IF NOT EXISTS diet_rule (id BIGINT PRIMARY KEY AUTO_INCREMENT, disease_code VARCHAR(60) NOT NULL, rule_type VARCHAR(20) NOT NULL, target_type VARCHAR(30) NOT NULL, target_value VARCHAR(150) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recommendation_config (id BIGINT PRIMARY KEY AUTO_INCREMENT, nutrition_weight DECIMAL(5,4) NOT NULL, preference_weight DECIMAL(5,4) NOT NULL, review_weight DECIMAL(5,4) NOT NULL, history_weight DECIMAL(5,4) NOT NULL, targets_json JSON, version INT NOT NULL, updated_by BIGINT, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_weight_nonnegative CHECK(nutrition_weight>=0 AND preference_weight>=0 AND review_weight>=0 AND history_weight>=0));
CREATE TABLE IF NOT EXISTS daily_menu (id BIGINT PRIMARY KEY AUTO_INCREMENT, site_id BIGINT NOT NULL, service_date DATE NOT NULL, meal_type VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', submitted_by BIGINT, submitted_at DATETIME, published_by BIGINT, published_at DATETIME, UNIQUE KEY uk_site_menu(site_id,service_date,meal_type), FOREIGN KEY(site_id) REFERENCES service_site(id));
CREATE TABLE IF NOT EXISTS daily_menu_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, menu_id BIGINT NOT NULL, dish_id BIGINT NOT NULL, planned_qty INT NOT NULL DEFAULT 0, serving_weight_grams DECIMAL(8,2), nutrition_override_json JSON, availability VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE', UNIQUE KEY uk_menu_dish(menu_id,dish_id), FOREIGN KEY(menu_id) REFERENCES daily_menu(id), FOREIGN KEY(dish_id) REFERENCES dish(id), CONSTRAINT ck_planned_qty CHECK(planned_qty>=0));
CREATE TABLE IF NOT EXISTS meal_order (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_no VARCHAR(64) NOT NULL UNIQUE, elder_id BIGINT NOT NULL, buyer_user_id BIGINT NOT NULL, proxy_operator_id BIGINT, site_id BIGINT NOT NULL, meal_date DATE NOT NULL, meal_type VARCHAR(20) NOT NULL, delivery_type VARCHAR(20) NOT NULL, delivery_address VARCHAR(255), contact_name VARCHAR(80), contact_phone VARCHAR(30), status VARCHAR(30) NOT NULL DEFAULT 'PENDING_PAYMENT', original_amount DECIMAL(10,2) NOT NULL, subsidy_amount DECIMAL(10,2) NOT NULL, payable_amount DECIMAL(10,2) NOT NULL, exception_flag TINYINT(1) NOT NULL DEFAULT 0, exception_note VARCHAR(500), pickup_code_hash VARCHAR(255), payment_expires_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_elder_meal(elder_id,meal_date,meal_type), KEY idx_site_meal(site_id,meal_date,meal_type), FOREIGN KEY(elder_id) REFERENCES elder(id), FOREIGN KEY(buyer_user_id) REFERENCES sys_user(id), FOREIGN KEY(site_id) REFERENCES service_site(id));
CREATE TABLE IF NOT EXISTS meal_order_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, menu_item_id BIGINT NOT NULL, dish_id BIGINT NOT NULL, dish_name_snapshot VARCHAR(120) NOT NULL, qty INT NOT NULL, original_unit_price DECIMAL(10,2) NOT NULL, actual_unit_price DECIMAL(10,2) NOT NULL, unit_subsidy DECIMAL(10,2) NOT NULL, nutrition_snapshot_json JSON, recommendation_event_id BIGINT, FOREIGN KEY(order_id) REFERENCES meal_order(id), FOREIGN KEY(menu_item_id) REFERENCES daily_menu_item(id), CONSTRAINT ck_order_item_qty CHECK(qty>0));
CREATE TABLE IF NOT EXISTS payment_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, channel VARCHAR(30) NOT NULL, payment_no VARCHAR(80) NOT NULL UNIQUE, gateway_transaction_no VARCHAR(100), amount DECIMAL(10,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', paid_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES meal_order(id));
CREATE TABLE IF NOT EXISTS refund_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, reason VARCHAR(500), status VARCHAR(30) NOT NULL DEFAULT 'PENDING_REVIEW', amount DECIMAL(10,2) NOT NULL, idempotency_key VARCHAR(80) NOT NULL UNIQUE, reviewed_by BIGINT, review_note VARCHAR(500), reviewed_at DATETIME, gateway_refund_no VARCHAR(100), refunded_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_refund_order(order_id), FOREIGN KEY(order_id) REFERENCES meal_order(id));
CREATE TABLE IF NOT EXISTS subsidy_ledger (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, amount DECIMAL(10,2) NOT NULL, entry_type VARCHAR(20) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_subsidy_order_type(order_id,entry_type), FOREIGN KEY(order_id) REFERENCES meal_order(id));
CREATE TABLE IF NOT EXISTS redemption (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL UNIQUE, verifier_user_id BIGINT NOT NULL, verified_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, verify_method VARCHAR(30) NOT NULL, FOREIGN KEY(order_id) REFERENCES meal_order(id));
CREATE TABLE IF NOT EXISTS delivery_record (order_id BIGINT PRIMARY KEY, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', delivered_at DATETIME, updated_by BIGINT, FOREIGN KEY(order_id) REFERENCES meal_order(id));
CREATE TABLE IF NOT EXISTS preparation_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, menu_item_id BIGINT NOT NULL UNIQUE, adjusted_qty INT, updated_by BIGINT, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(menu_item_id) REFERENCES daily_menu_item(id), CONSTRAINT ck_preparation_qty CHECK(adjusted_qty IS NULL OR adjusted_qty>=0));
CREATE TABLE IF NOT EXISTS attendance_daily (id BIGINT PRIMARY KEY AUTO_INCREMENT, site_id BIGINT NOT NULL, attendance_date DATE NOT NULL, meal_type VARCHAR(20) NOT NULL, diner_count INT NOT NULL, is_open TINYINT(1) NOT NULL DEFAULT 1, UNIQUE KEY uk_daily_attend(site_id,attendance_date,meal_type), FOREIGN KEY(site_id) REFERENCES service_site(id), CONSTRAINT ck_diner_count CHECK(diner_count>=0));
CREATE TABLE IF NOT EXISTS forecast_result (id BIGINT PRIMARY KEY AUTO_INCREMENT, site_id BIGINT NOT NULL, meal_type VARCHAR(20) NOT NULL, target_date DATE NOT NULL, predicted_count INT, closed TINYINT(1) NOT NULL DEFAULT 0, insufficient_data TINYINT(1) NOT NULL DEFAULT 0, sample_count INT NOT NULL, algorithm VARCHAR(40) NOT NULL, sample_dates_json JSON, generated_at DATETIME DEFAULT CURRENT_TIMESTAMP, KEY idx_forecast(site_id,meal_type,target_date), FOREIGN KEY(site_id) REFERENCES service_site(id));
CREATE TABLE IF NOT EXISTS recommendation_event (id BIGINT PRIMARY KEY AUTO_INCREMENT, elder_id BIGINT NOT NULL, menu_item_id BIGINT NOT NULL, score DECIMAL(6,2), reasons_json JSON, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, KEY idx_rec_elder(elder_id,created_at), FOREIGN KEY(elder_id) REFERENCES elder(id), FOREIGN KEY(menu_item_id) REFERENCES daily_menu_item(id));
CREATE TABLE IF NOT EXISTS dish_review (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_item_id BIGINT NOT NULL UNIQUE, reviewer_user_id BIGINT NOT NULL, rating TINYINT NOT NULL, content TEXT, image_file_ids_json JSON, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_item_id) REFERENCES meal_order_item(id), CONSTRAINT ck_rating CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE IF NOT EXISTS feedback_ticket (id BIGINT PRIMARY KEY AUTO_INCREMENT, site_id BIGINT NOT NULL, created_by BIGINT NOT NULL, order_id BIGINT, type VARCHAR(30) NOT NULL, content TEXT NOT NULL, image_file_ids_json JSON, status VARCHAR(30) NOT NULL DEFAULT 'OPEN', priority VARCHAR(20) NOT NULL DEFAULT 'NORMAL', first_reply_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(site_id) REFERENCES service_site(id));
CREATE TABLE IF NOT EXISTS ticket_reply (id BIGINT PRIMARY KEY AUTO_INCREMENT, ticket_id BIGINT NOT NULL, user_id BIGINT NOT NULL, content TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ticket_id) REFERENCES feedback_ticket(id));
CREATE TABLE IF NOT EXISTS notice (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200) NOT NULL, type VARCHAR(30) NOT NULL, content TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', target_roles_json JSON, target_sites_json JSON, publish_at DATETIME, expire_at DATETIME, created_by BIGINT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stored_file (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_user_id BIGINT NOT NULL, purpose VARCHAR(30) NOT NULL, storage_path VARCHAR(300) NOT NULL, content_type VARCHAR(80) NOT NULL, size_bytes BIGINT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_user_id) REFERENCES sys_user(id));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, operator_user_id BIGINT, action VARCHAR(80) NOT NULL, resource_type VARCHAR(60), resource_id VARCHAR(80), success TINYINT(1) NOT NULL, summary VARCHAR(500), ip_masked VARCHAR(80), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, KEY idx_audit_time(created_at));
INSERT IGNORE INTO sys_role (id,code,name) VALUES (1,'ADMIN','系统管理员'),(2,'CANTEEN','食堂工作人员'),(3,'FAMILY','老年人家属'),(4,'COMMUNITY','社区操作员');
INSERT IGNORE INTO recommendation_config (id,nutrition_weight,preference_weight,review_weight,history_weight,version) VALUES (1,0.4000,0.2500,0.2000,0.1500,1);
-- 实现注意：跨表约束（订单唯一活跃、份数占位、金额快照、用户资源权限、补贴资格）需在 Service 事务中实现，无法仅靠上述 DDL 保证。
-- 首版文档用途是可执行的起始 Schema，迭代中通过迁移脚本补充索引、字段、字段字典与外键。
